    return 0


@command("top", "show the most frequent words in the text", [("text", {}), ("--k", {"default": "3"})])
def _top(a):
    try:
        k = int(a.k)
    except ValueError:
        k = a.k
    for word, n in topwords.top_words(a.text, k):
        print(f"{word} {n}")
    return 0


